using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using NUnit.Framework;
using RA2YR.Core.Binary;
using RA2YR.Core.Content;
using RA2YR.Core.Formats.Ini;
using RA2YR.Core.Formats.Tmp;

namespace RA2YR.Tests.EditMode.Formats.Tmp
{
    public sealed class TmpTheaterTests
    {
        [Test] public void MinimalOneByOneGridParses52ByteCell() { TmpDocument d = Read(BuildTmp(1, 1, 24, Cell(0), new byte[] { 0x7A }), 2, 1); Assert.That(d.IsSuccess, Is.True); Assert.That(d.Cells.Count, Is.EqualTo(1)); Assert.That(d.Cells[0].Header.GetRawBytesCopy().Length, Is.EqualTo(52)); }
        [Test] public void ZeroOffsetIsEmptySlot() { TmpDocument d = Read(BuildTmp(1, 1, 0, null, Array.Empty<byte>()), 2, 1); Assert.That(d.IsSuccess, Is.True); Assert.That(d.EmptySlotCount, Is.EqualTo(1)); Assert.That(d.Cells, Is.Empty); }
        [Test] public void NegativeOffsetFailsClosed() { TmpDocument d = Read(BuildTmpRaw(1, 1, unchecked((uint)-1), null, Array.Empty<byte>()), 2, 1); Assert.That(d.IsSuccess, Is.False); Assert.That(d.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.NegativeOffset), Is.True); }
        [Test] public void HeaderAreaOffsetFails() { TmpDocument d = Read(BuildTmpRaw(1, 1, 8, null, Array.Empty<byte>()), 2, 1); Assert.That(d.IsSuccess, Is.False); Assert.That(d.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.OffsetInsideHeader), Is.True); }
        [Test] public void OffsetTableAreaOffsetFails() { TmpDocument d = Read(BuildTmpRaw(1, 1, 16, null, Array.Empty<byte>()), 2, 1); Assert.That(d.IsSuccess, Is.False); Assert.That(d.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.OffsetInsideOffsetTable), Is.True); }
        [Test] public void TruncatedCellHeaderFailsAt51Bytes() { byte[] bytes = BuildTmp(1, 1, 24, null, Array.Empty<byte>()); Array.Resize(ref bytes, 24 + 51); TmpDocument d = Read(bytes, 2, 1); Assert.That(d.IsSuccess, Is.False); Assert.That(d.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.OffsetOutsideWindow), Is.True); }
        [Test] public void HeaderFieldsAndUnknownFlagsArePreserved() { byte[] h = Cell(0xAABBCCDD); WriteU32(h, 8, 0x01020304); WriteU32(h, 12, 0x05060708); WriteU32(h, 16, 0x090A0B0C); WriteU32(h, 36, 0x80000007); h[40] = 0xFE; h[41] = 0xDD; h[42] = 0xCC; h[49] = 1; h[50] = 2; h[51] = 3; TmpDocument d = Read(BuildTmp(1, 1, 24, h, new byte[] { 0x11 }), 2, 1); TmpCellHeaderRaw r = d.Cells[0].Header; Assert.That(r.ExtraColorOffsetRawU32, Is.EqualTo(0x01020304u)); Assert.That(r.DiamondDepthOffsetRawU32, Is.EqualTo(0x05060708u)); Assert.That(r.FlagsRawU32, Is.EqualTo(0x80000007u)); Assert.That(r.Trailing2Raw, Is.EqualTo(3)); Assert.That(d.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.UnknownFlags), Is.True); }
        [Test] public void RawHeaderDoesNotInterpretHeightTerrainRamp() { TmpDocument d = Read(BuildTmp(1, 1, 24, Cell(0), new byte[] { 1 }), 2, 1); Assert.That(d.Cells[0].Header.HeightRaw, Is.EqualTo(0)); Assert.That(d.Cells[0].Header.TerrainTypeRaw, Is.EqualTo(0)); Assert.That(d.Cells[0].Header.RampTypeRaw, Is.EqualTo(0)); }
        [Test] public void DiamondLengthUsesCheckedCanonicalProfile() { byte[] payload = Enumerable.Repeat((byte)7, 900).ToArray(); TmpDocument d = Read(BuildTmp(1, 1, 24, Cell(0), payload), 60, 30); Assert.That(d.IsSuccess, Is.True); Assert.That(d.Cells[0].PlaneDirectory.Find("DiamondColor").Length, Is.EqualTo(900)); }
        [Test] public void InvalidDiamondProfileFailsWithoutRepair() { TmpDocument d = Read(BuildTmp(1, 1, 24, Cell(0), new byte[] { 1 }), 3, 2); Assert.That(d.IsSuccess, Is.False); Assert.That(d.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.DiamondProfileMismatch), Is.True); }
        [Test] public void TruncatedDiamondIsNotPadded() { TmpDocument d = Read(BuildTmp(1, 1, 24, Cell(0), new byte[] { 1 }), 60, 30); Assert.That(d.IsSuccess, Is.False); Assert.That(d.Cells[0].PlaneDirectory.Find("DiamondColor").GetBytesCopy(), Is.Empty); }
        [Test] public void ExtraPlaneUsesCheckedRectangleArea() { byte[] h = Cell(1); WriteU32(h, 8, 53); WriteU32(h, 28, 2); WriteU32(h, 32, 2); TmpDocument d = Read(BuildTmp(1, 1, 24, h, new byte[] { 1, 2, 3, 4, 5 }), 2, 1); Assert.That(d.IsSuccess, Is.True); Assert.That(d.Cells[0].PlaneDirectory.Find("ExtraColor").Length, Is.EqualTo(4)); }
        [Test] public void DeclaredDepthOffsetIsExplicitlyUsed() { byte[] h = Cell(2); WriteU32(h, 12, 53); byte[] payload = new byte[] { 1, 9 }; TmpDocument d = Read(BuildTmp(1, 1, 24, h, payload), 2, 1, TmpPlaneLayoutPolicy.DeclaredOffsets); Assert.That(d.Cells[0].PlaneDirectory.Find("DiamondDepth").GetBytesCopy(), Is.EqualTo(new byte[] { 9 })); }
        [Test] public void SequentialPolicyDoesNotFallbackToDeclaredOffset() { byte[] h = Cell(2); WriteU32(h, 12, 100); byte[] payload = new byte[] { 1, 9 }; TmpDocument d = Read(BuildTmp(1, 1, 24, h, payload), 2, 1, TmpPlaneLayoutPolicy.SequentialWithZ); Assert.That(d.Cells[0].PlaneDirectory.Find("DiamondDepth").GetBytesCopy(), Is.EqualTo(new byte[] { 9 })); }
        [Test] public void PlaneOverlapIsDiagnostic() { byte[] h = Cell(3); WriteU32(h, 12, 53); WriteU32(h, 8, 53); WriteU32(h, 28, 1); WriteU32(h, 32, 1); byte[] payload = new byte[] { 1, 2 }; TmpDocument d = Read(BuildTmp(1, 1, 24, h, payload), 2, 1, TmpPlaneLayoutPolicy.DeclaredOffsets); Assert.That(d.IsSuccess, Is.False); Assert.That(d.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.PlaneOverlap), Is.True); }
        [Test] public void TrailingPlaneBytesAreReportedNotSwallowed() { TmpDocument d = Read(BuildTmp(1, 1, 24, Cell(0), new byte[] { 1, 2, 3 }), 2, 1, TmpPlaneLayoutPolicy.SequentialWithoutZ); Assert.That(d.IsSuccess, Is.True); Assert.That(d.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.TrailingBytes), Is.True); }
        [Test] public void DuplicateOffsetsAreBounded() { byte[] bytes = BuildTmp(2, 1, 24, Cell(0), new byte[] { 1 }); WriteU32(bytes, 20, 24); TmpDocument d = Read(bytes, 2, 1); Assert.That(d.Cells.Count, Is.EqualTo(2)); Assert.That(d.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.DuplicateCellOffset), Is.True); }
        [Test] public void ReversedOffsetsRetainSlotOrder() { byte[] bytes = BuildTmp(2, 1, 40, Cell(0), new byte[] { 1 }); byte[] h = Cell(0); Buffer.BlockCopy(h, 0, bytes, 24, 52); WriteU32(bytes, 16, 40); WriteU32(bytes, 20, 24); TmpDocument d = Read(bytes, 2, 1); Assert.That(d.OffsetTable[0].SlotOrdinal, Is.EqualTo(0)); Assert.That(d.OffsetTable[1].SlotOrdinal, Is.EqualTo(1)); }
        [Test] public void InputBudgetFailsBeforeSnapshot() { TmpDocument d = Read(BuildTmp(1, 1, 24, Cell(0), new byte[] { 1 }), 2, 1, TmpPlaneLayoutPolicy.DeclaredOffsets, new TmpReadLimits(maxInputBytes: 1)); Assert.That(d.IsSuccess, Is.False); Assert.That(d.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.InputBudgetExceeded), Is.True); }
        [Test] public void MemoryAndStreamUseSameParser() { byte[] bytes = BuildTmp(1, 1, 24, Cell(0), new byte[] { 1 }); TmpDocument memory = Read(bytes, 2, 1); using (var stream = new MemoryStream(bytes)) { TmpDocument streamed = TmpRawReader.Read(stream, bytes.Length, Source(), Provenance(), new TmpReadPolicy(2, 1)); Assert.That(streamed.CanonicalSha256, Is.EqualTo(memory.CanonicalSha256)); Assert.That(streamed.Cells.Count, Is.EqualTo(memory.Cells.Count)); } }
        [Test] public void AllSixTheaterProfilesRemainDistinct() { Assert.That(TheaterProfiles.All.Select(p => p.Kind).Distinct().Count(), Is.EqualTo(6)); Assert.That(TheaterProfiles.Get(TheaterKind.NewUrban).OptionalFallbackTmpExtensions, Does.Contain(".urb")); }
        [Test] public void RegistryAllocatesCumulativeRanges() { TheaterTileRegistry r = Registry(new[]{ Set(0, "clear", 2), Set(1, "rough", 3) }); Assert.That(r.IdRanges[0].StartInclusive, Is.EqualTo(0)); Assert.That(r.IdRanges[1].StartInclusive, Is.EqualTo(2)); Assert.That(r.IdRanges[1].EndExclusive, Is.EqualTo(5)); }
        [Test] public void RegistryRetainsNumericGap() { TheaterTileRegistry r = Registry(new[]{ Set(0, "clear", 2), Set(2, "rough", 3) }); Assert.That(r.TileSets.Count, Is.EqualTo(2)); Assert.That(r.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.TileSetGap), Is.True); }
        [Test] public void RegistryRejectsNegativeTilesInSet() { TheaterTileRegistry r = Registry(new[]{ Set(0, "clear", -1) }); Assert.That(r.IsSuccess, Is.False); Assert.That(r.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.NegativeTilesInSet), Is.True); }
        [Test] public void RegistryRejectsZeroTilesInSet() { TheaterTileRegistry r = Registry(new[]{ Set(0, "clear", 0) }); Assert.That(r.IsSuccess, Is.False); Assert.That(r.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.ZeroTilesInSet), Is.True); }
        [Test] public void MissingAssetsDoNotChangeLaterGlobalRange() { TheaterTileRegistry r = Registry(new[]{ Set(0, "clear", 2), Set(1, "rough", 3) }); var provider = new FakeProvider(); provider.Add("rough01.tem", "source", true); TmpAssetResolutionTrace trace = TmpAssetResolver.Resolve(r, TheaterProfiles.Get(TheaterKind.Temperate), 1, 0, provider, new TmpAssetResolutionPolicy(TmpVariationPolicy.BaseOnly)); Assert.That(trace.GlobalTileId, Is.EqualTo(2)); }
        [Test] public void AssetNumberingIsOneBasedAndTwoDigit() { TheaterTileRegistry r = Registry(new[]{ Set(0, "clear", 12) }); var provider = new FakeProvider(); provider.Add("clear02.tem", "source", true); TmpAssetResolutionTrace trace = TmpAssetResolver.Resolve(r, TheaterProfiles.Get(TheaterKind.Temperate), 0, 1, provider, new TmpAssetResolutionPolicy(TmpVariationPolicy.BaseOnly)); Assert.That(trace.Candidates[0].LogicalName, Is.EqualTo("clear02.tem")); Assert.That(trace.Selected, Is.Not.Null); }
        [Test] public void VariationsRequireExplicitPolicy() { TheaterTileRegistry r = Registry(new[]{ Set(0, "clear", 1) }); var provider = new FakeProvider(); provider.Add("clear01a.tem", "source", true); TmpAssetResolutionTrace disabled = TmpAssetResolver.Resolve(r, TheaterProfiles.Get(TheaterKind.Temperate), 0, 0, provider, new TmpAssetResolutionPolicy(TmpVariationPolicy.BaseOnly)); Assert.That(disabled.Selected, Is.Null); TmpAssetResolutionTrace enabled = TmpAssetResolver.Resolve(r, TheaterProfiles.Get(TheaterKind.Temperate), 0, 0, provider, new TmpAssetResolutionPolicy(TmpVariationPolicy.BaseAndAThroughF)); Assert.That(enabled.Selected, Is.Not.Null); Assert.That(enabled.Selected.Variation, Is.EqualTo("a")); }
        [Test] public void NewUrbanFallbackIsExplicit() { TheaterTileRegistry r = Registry(new[]{ Set(0, "clear", 1) }); var provider = new FakeProvider(); provider.Add("clear01.urb", "editor", true); TmpAssetResolutionTrace disabled = TmpAssetResolver.Resolve(r, TheaterProfiles.Get(TheaterKind.NewUrban), 0, 0, provider, new TmpAssetResolutionPolicy(TmpVariationPolicy.BaseOnly, TmpFallbackExtensionPolicy.Disabled)); Assert.That(disabled.Selected, Is.Null); TmpAssetResolutionTrace enabled = TmpAssetResolver.Resolve(r, TheaterProfiles.Get(TheaterKind.NewUrban), 0, 0, provider, new TmpAssetResolutionPolicy(TmpVariationPolicy.BaseOnly, TmpFallbackExtensionPolicy.ExplicitNewUrbanEditorCandidate)); Assert.That(enabled.Selected, Is.Not.Null); Assert.That(enabled.Selected.Extension, Is.EqualTo(".urb")); }
        [Test] public void ProviderCaseCollisionFailsClosed() { TheaterTileRegistry r = Registry(new[]{ Set(0, "clear", 1) }); var provider = new FakeProvider(); provider.Add("clear01.tem", "a", true); provider.Add("clear01.tem", "b", true); TmpAssetResolutionTrace trace = TmpAssetResolver.Resolve(r, TheaterProfiles.Get(TheaterKind.Temperate), 0, 0, provider, new TmpAssetResolutionPolicy(TmpVariationPolicy.BaseOnly)); Assert.That(trace.IsSuccess, Is.False); Assert.That(trace.Diagnostics.Any(x => x.Code == TmpDiagnosticCode.AmbiguousAssetCandidate), Is.True); }
        [Test] public void GlobalTileIdLookupIsChecked() { TheaterTileRegistry r = Registry(new[]{ Set(0, "clear", 2) }); TheaterTileIdRange range; int local; Assert.That(r.TryResolveGlobalTileId(1, out range, out local), Is.True); Assert.That(local, Is.EqualTo(1)); Assert.That(r.TryResolveGlobalTileId(2, out range, out local), Is.False); }
        [Test] public void SpecialRoleReferencesRangeWithoutSemanticPromotion() { TheaterControlDocument d = Document(new[]{ Set(0, "clear", 2) }, new[]{ Value("General", "WaterSet", "0", 0) }); TheaterTileRegistry r = TheaterTileRegistryBuilder.Build(d); Assert.That(r.SpecialRoles.Single(x => x.Role == "WaterSet").Range, Is.Not.Null); }

        private static TmpDocument Read(byte[] bytes, int width, int height, TmpPlaneLayoutPolicy layout = TmpPlaneLayoutPolicy.DeclaredOffsets, TmpReadLimits limits = null) => TmpRawReader.Read(bytes, Source(), Provenance(), new TmpReadPolicy(width, height, layout, limits));
        private static byte[] BuildTmp(int blocksX, int blocksY, int cellOffset, byte[] header, byte[] payload) => BuildTmpRaw(blocksX, blocksY, unchecked((uint)cellOffset), header, payload);
        private static byte[] BuildTmpRaw(int blocksX, int blocksY, uint cellOffset, byte[] header, byte[] payload)
        { int baseOffset = cellOffset == 0 || cellOffset > int.MaxValue ? 16 : (int)cellOffset; int length = Math.Max(16 + blocksX * blocksY * 4, baseOffset + (header == null ? 0 : 52) + (payload == null ? 0 : payload.Length)); byte[] bytes = new byte[length]; WriteU32(bytes, 0, (uint)blocksX); WriteU32(bytes, 4, (uint)blocksY); WriteU32(bytes, 8, 0); WriteU32(bytes, 12, 0); WriteU32(bytes, 16, cellOffset); if (header != null && header.Length != 0 && cellOffset <= int.MaxValue && baseOffset + header.Length <= bytes.Length) Buffer.BlockCopy(header, 0, bytes, baseOffset, header.Length); if (payload != null && payload.Length != 0 && cellOffset <= int.MaxValue && baseOffset + 52 + payload.Length <= bytes.Length) Buffer.BlockCopy(payload, 0, bytes, baseOffset + 52, payload.Length); return bytes; }
        private static byte[] Cell(uint flags) { byte[] b = new byte[52]; WriteU32(b, 36, flags); return b; }
        private static void WriteU32(byte[] bytes, int offset, uint value) { bytes[offset] = (byte)value; bytes[offset + 1] = (byte)(value >> 8); bytes[offset + 2] = (byte)(value >> 16); bytes[offset + 3] = (byte)(value >> 24); }
        private static BinarySourceContext Source() => new BinarySourceContext("tmp-tests", "tmp-tests", LogicalContentPath.Parse("tmp-tests.bin"));
        private static IniSourceProvenance Provenance() => new IniSourceProvenance("tmp-tests", new[]{ LogicalContentPath.Parse("tmp-tests.ini") });
        private static TheaterTileSetDescriptor Set(int index, string file, int count) { TheaterValueView fileValue = Value("TileSet" + index.ToString("D4"), "FileName", file, null); TheaterValueView countValue = Value("TileSet" + index.ToString("D4"), "TilesInSet", count.ToString(CultureInfo.InvariantCulture), count); return new TheaterTileSetDescriptor(index, fileValue.Section, file, count, fileValue, new[]{ fileValue, countValue }); }
        private static TheaterValueView Value(string section, string key, string raw, int? integer) => new TheaterValueView(section, key, raw, integer, Provenance(), 0, 0, Array.Empty<RA2YR.Core.Configuration.Ini.Resolution.IniResolvedValueCandidate>());
        private static TheaterControlDocument Document(IEnumerable<TheaterTileSetDescriptor> sets, IEnumerable<TheaterValueView> extra)
        { var values = new List<TheaterValueView>(); foreach (TheaterTileSetDescriptor set in sets) values.AddRange(set.Values); values.AddRange(extra); return new TheaterControlDocument(TheaterProfiles.Get(TheaterKind.Temperate), values.FirstOrDefault(), values, Array.Empty<TmpDiagnostic>(), new TmpExecutionState()); }
        private static TheaterTileRegistry Registry(IEnumerable<TheaterTileSetDescriptor> sets) => TheaterTileRegistryBuilder.Build(Document(sets, Array.Empty<TheaterValueView>()));

        private sealed class FakeProvider : ITmpAssetProvider
        {
            private readonly Dictionary<string, List<TmpAssetProviderCandidate>> map = new Dictionary<string, List<TmpAssetProviderCandidate>>(StringComparer.OrdinalIgnoreCase);
            public void Add(string logicalName, string providerId, bool exists) { if (!map.TryGetValue(logicalName, out List<TmpAssetProviderCandidate> list)) map[logicalName] = list = new List<TmpAssetProviderCandidate>(); list.Add(new TmpAssetProviderCandidate(logicalName, providerId, exists, Provenance())); }
            public IReadOnlyList<TmpAssetProviderCandidate> ResolveCandidates(string logicalName) => map.TryGetValue(logicalName, out List<TmpAssetProviderCandidate> list) ? list : Array.Empty<TmpAssetProviderCandidate>();
        }
    }
}
